create function private.backup_object_readable(path text) returns boolean language sql stable security definer set search_path='' as $$select private.is_admin() and exists(select 1 from private.work_jobs j where j.organization_id=private.actor_org() and j.kind='backup' and j.status='succeeded' and split_part(path,'/',1)=j.organization_id::text and split_part(path,'/',2)=j.id::text)$$; revoke all on function private.backup_object_readable(text) from public,anon; grant execute on function private.backup_object_readable(text) to authenticated; alter policy backup_admin_read on storage.objects using(bucket_id='system-backups' and private.backup_object_readable(name));